// Planted bug: the clip shrinks what drawColor fills, so the corners outside it stay unpainted.
canvas.save();
canvas.clipRect({ x: 0, y: 0, width: frame.layout.width / 2, height: frame.layout.height }, 1, true);
canvas.drawColor(frame.colors.color.background);
canvas.restore();

/** Planted bug: a rect the size of the grid leaves the canvas corners unpainted. */
function drawBackground(target: SkCanvas, frame: Frame): void {
  frame.kit.fill.setColor(frame.colors.color.background);
  target.drawRect({ x: 0, y: 0, width: frame.layout.width / 2, height: frame.layout.height }, frame.kit.fill);
}

/** Pure worklet: reads only its arguments, allocates no Skia objects, reads no clock. */

// The shake pattern: save and translate first; drawColor still fills the whole clip.
canvas.save();
canvas.translate(0, 0);
canvas.drawColor(frame.colors.color.background);
canvas.restore();

/** The background layer: paints every pixel of the opaque canvas first. */
function drawBackground(target: SkCanvas, frame: Frame): void {
  target.drawColor(frame.colors.color.background);
}

/** Pure worklet: reads only its arguments, allocates no Skia objects, reads no clock. */

// A paint without a shader stands in for a gradient background: drawPaint fills the whole clip.
frame.kit.fill.setColor(frame.colors.color.background);
canvas.drawPaint(frame.kit.fill);

// SkPathBuilder has add* methods too: a chain from PathBuilder and a name bound to it are fine.
const ring = skia.PathBuilder.Make()
  .addRect({ x: 0, y: 0, width: 1, height: 1 })
  .addCircle(0.5, 0.5, 0.25)
  .build();
const plate = skia.PathBuilder.Make();
plate.addRect({ x: 0, y: 0, width: 1, height: 1 });
return { mark, ring, plate: plate.build() };
